modules.code:
variables
{
  msTimer heartbeat;
  message 0x300 Heartbeat;
}
on start
{
  Heartbeat.dlc = 1;
  Heartbeat.byte(0) = 1;
  setTimer(heartbeat, 100);
}
on timer heartbeat
{
  output(Heartbeat);
  // Rearm the timer here
}
on key 's'
{
  cancelTimer(heartbeat);
}
on key 'r'
{
  setTimer(heartbeat, 100);
}

