modules.code:
variables
{
  msTimer watchdog;
  int timedOut = 0;
}
on start
{
  setTimer(watchdog, 500);
}
on message 0x300
{
  timedOut = 0;
  // Rearm on reception here
}
on timer watchdog
{
  timedOut = 1;
  write("Communication timeout");
}

